import { ConfigPlugin } from '@znight/config'
import { Application } from '@znight/core'
import { ObservabilityPlugin } from '@znight/observability'

// Generated by the compiler (znight generate, vite build, bun test): every provider, its
// dependencies and the route table, the access decision of every route included.
import { __ZNIGHT_METADATA__ } from './.znight/container.generated.js'
import { ServerConfig } from './config/server.config.js'
import { httpPlugin } from './http.js'

const app = await Application.create({
  metadata: __ZNIGHT_METADATA__,
  plugins: [
    // First, so that its hooks wrap everything else: one JSON log line per request, with its requestId.
    ObservabilityPlugin.configure(container => ({
      logging: {
        level: container.get(ServerConfig).logLevel,
        requests: { ignore: event => event.route === '/health' },
        // Znight's request logs hold no header. Should a log entry ever carry headers (a request
        // logged by hand, an error with its request), credentials are censored.
        redact: ['*.headers.authorization', '*.headers.cookie', '*.headers["x-api-key"]', '*.headers["x-signature"]'],
      },
      metrics: false,
    })),
    // .env files then the environment, validated before anything is created: a missing
    // SESSION_SECRETS stops the boot with every problem listed (ZNIGHT006), secrets never printed.
    ConfigPlugin.configure(),
    // Guards, CORS, security headers, trusted proxies and cookie secrets, shared with the tests.
    httpPlugin(),
  ],
  // SIGINT / SIGTERM: the HTTP server stops accepting connections and drains in-flight requests,
  // providers stop. Keep `timeoutMs` below the grace period of your platform.
  shutdown: { timeoutMs: 8_000, hookTimeoutMs: 5_000 },
})

await app.start()
